-- MP-0029: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='perikatan-nasional' and type='alliance') then raise exception 'MP-0029: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('abdul-khalib-abdullah','kalam-salan','muslimin-yahaya') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0029: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('rompin','sabak bernam','sungai besar') and slug not in ('abdul-khalib-abdullah','kalam-salan','muslimin-yahaya')) then raise exception 'MP-0029: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0029:%' and (m.source_type <> 'editorial' or e.slug not in ('abdul-khalib-abdullah','kalam-salan','muslimin-yahaya') or m.import_key not like 'MP-0029:' || e.slug || ':%')) then raise exception 'MP-0029: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'abdul-khalib-abdullah','Abdul Khalib Abdullah','opposition','Member of the Dewan Rakyat','Rompin','Pahang','Abdul Khalib Abdullah represents Rompin, Pahang, in the Dewan Rakyat. Parliament records affiliation with Perikatan Nasional (PN).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4130','/portraits/abdul-khalib-abdullah.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P091.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4130"}, {"label": "Parliament · current Dewan Rakyat directory", "url": "https://www.parlimen.gov.my/ahli-dewan.html?uweb=dr"}]'::jsonb from public.entities parent where parent.slug='perikatan-nasional' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'kalam-salan','Kalam Salan','opposition','Member of the Dewan Rakyat','Sabak Bernam','Selangor','Kalam Salan represents Sabak Bernam, Selangor, in the Dewan Rakyat. Parliament records affiliation with Perikatan Nasional (PN).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4131','/portraits/kalam-salan.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P092.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4131"}, {"label": "Parliament · current Dewan Rakyat directory", "url": "https://www.parlimen.gov.my/ahli-dewan.html?uweb=dr"}]'::jsonb from public.entities parent where parent.slug='perikatan-nasional' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'muslimin-yahaya','Muslimin Yahaya','opposition','Member of the Dewan Rakyat','Sungai Besar','Selangor','Muslimin Yahaya represents Sungai Besar, Selangor, in the Dewan Rakyat. Parliament records affiliation with Perikatan Nasional (PN).','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4132','/portraits/muslimin-yahaya.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P093.png','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4132"}, {"label": "Parliament · current Dewan Rakyat directory", "url": "https://www.parlimen.gov.my/ahli-dewan.html?uweb=dr"}]'::jsonb from public.entities parent where parent.slug='perikatan-nasional' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('abdul-khalib-abdullah','kalam-salan','muslimin-yahaya') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0029: concurrent ownership or identity change'; end if; end $$;

commit;
